// Example demonstrates loading an OpenXLA PJRT plugin and querying platform info.
func Example() {
	plugin, err := openxla.OpenPlugin("/usr/lib/libtpu.so")
	if err != nil {
		fmt.Println("PJRT plugin unavailable:", err)
		return
	}

	api := plugin.Api()
	fmt.Printf("PJRT API Version: %d.%d\n", api.ApiVersion.Major_version, api.ApiVersion.Minor_version)

	client, err := plugin.NewClient()
	if err != nil {
		fmt.Println("NewClient:", err)
		return
	}
	defer client.Destroy()

	name, _ := client.PlatformName()
	ver, _ := client.PlatformVersion()
	fmt.Printf("Platform: %s (%s)\n", name, ver)
}
